def decode_hex(text: str) -> bytes | None:
    if len(text)%2: return None
    if any(ord(c)>127 or c not in '0123456789abcdefABCDEF' for c in text): return None
    return bytes(int(text[i:i+2],16) for i in range(0,len(text),2))
